// reproduce.js
// 1. Install lighthouse (npm install lighthouse) and save this file
// 2. Run with: node reproduce.js

const Audit = require('lighthouse/lighthouse-core/audits/user-timings.js');
const GatherRunner = require('lighthouse/lighthouse-core/gather/gather-runner.js');
const computedArtifacts = GatherRunner.instantiateComputedArtifacts();

// Simulate a traceEvents array that includes both Google Ads marks and your own marks/measures.
const traceEvents = [
  // Google Ads marks (prefix ad_* and goog_*)
  { cat: 'blink.user_timing', ph: 'R', ts: 3919.77, name: 'ad_slots_defined', args: { data: {} } },
  { cat: 'blink.user_timing', ph: 'R', ts: 4374.90, name: 'ad_requested_from_server', args: { data: {} } },
  { cat: 'blink.user_timing', ph: 'b', ts: 8466.17, name: 'goog_123_3_1_start', args: { data: {} } },
  { cat: 'blink.user_timing', ph: 'e', ts: 8468.09, name: 'goog_123_3_1_end', args: { data: {} } },
  // Your own application mark and measure
  { cat: 'blink.user_timing', ph: 'R', ts: 5000,     name: 'app_custom_mark', args: { data: {} } },
  { cat: 'blink.user_timing', ph: 'b', ts: 6000,     name: 'app_custom_measure', args: { data: {} } },
  { cat: 'blink.user_timing', ph: 'e', ts: 6500,     name: 'app_custom_measure', args: { data: {} } }
];

// Build the artifacts object expected by the audit
const artifacts = Object.assign(computedArtifacts, {
  traces: {
    [Audit.DEFAULT_PASS]: {traceEvents}
  }
});

// Run the audit
Audit.audit(artifacts).then(auditResult => {
  console.log(`DisplayValue (count): ${auditResult.displayValue}`);
  console.log('=== All user-timing items: ===');
  auditResult.extendedInfo.value.forEach(item => {
    console.log(
      `${item.isMark ? 'Mark:' : 'Measure:'} ${item.name}  ` +
      `start=${item.startTime.toFixed(2)}  ` +
      (item.duration ? `duration=${item.duration.toFixed(2)}` : '')
    );
  });
}).catch(err => console.error(err));
